class CustomerPresenter:
    def __init__(self, width: int = 40) -> None:
        self._width = width

    def describe(self, customer) -> str:
        parts = [
            str(customer.customer_id()),
            customer.name(),
            customer.email(),
            customer.tier(),
        ]
        return " | ".join(parts).ljust(self._width)
```
Inject it into `ReportView` (or instantiate locally) and replace the old `describe_customer` method with a thin delegator or remove it entirely:
```python
class ReportView:
    def __init__(self, repository: OrderRepository, mailer: EmailClient, presenter: CustomerPresenter) -> None:
        self._repository = repository
        self._mailer = mailer
        self._presenter = presenter
        self._width = 40

    # keep title, order_count, mail_summary unchanged
    def describe_customer(self, customer) -> str:
        return self._presenter.describe(customer)
```
